import crypto from 'node:crypto';
import jwt from 'jsonwebtoken';

// ❌ fast hash, no salt, no constant-time compare
function hashPassword(pw) {
  return crypto.createHash('sha256').update(pw).digest('hex');
}
function checkPassword(pw, stored) {
  return crypto.createHash('sha256').update(pw).digest('hex') === stored;
}

// ❌ trusts the token's header: accepts alg:none and RS256/HS256 confusion
function readToken(token, key) {
  return jwt.verify(token, key);
}

model.en:
Slow, salted KDF + constant-time compare, and a pinned verify:

import crypto from 'node:crypto';
import jwt from 'jsonwebtoken';

function hashPassword(pw) {
  const salt = crypto.randomBytes(16);                       // unique per user
  const key = crypto.scryptSync(pw, salt, 64, { N: 16384, r: 8, p: 1 });
  return `scrypt$${salt.toString('hex')}$${key.toString('hex')}`;
}

function checkPassword(pw, stored) {
  const [, saltHex, keyHex] = stored.split('$');
  const salt = Buffer.from(saltHex, 'hex');
  const expected = Buffer.from(keyHex, 'hex');
  const actual = crypto.scryptSync(pw, salt, expected.length, { N: 16384, r: 8, p: 1 });
  return crypto.timingSafeEqual(actual, expected); // constant-time
}

function readToken(token, key) {
  return jwt.verify(token, key, {
    algorithms: ['RS256'],          // never let the token choose → kills alg:none + HS/RS confusion
    issuer: 'https://auth.example.com',
    audience: 'api://orders',
    maxAge: '15m',
  });
}

Why it's right: scrypt is slow and memory-hard tuned to ~100-250 ms, so a GPU's billions-per-second collapses to a few guesses/core; the per-user random salt defeats rainbow tables; timingSafeEqual scans the full length so byte-by-byte timing recovery is impossible. Pinning algorithms to a single allow-listed value stops both alg:none (no signature check) and RS256/HS256 confusion (signing with the public key as an HMAC secret); issuer/audience/maxAge ensure the token was minted for you and isn't immortal.

model.ru:
Медленный, солёный KDF + сравнение за постоянное время и закреплённый verify:

import crypto from 'node:crypto';
import jwt from 'jsonwebtoken';

function hashPassword(pw) {
  const salt = crypto.randomBytes(16);                       // уникальная на пользователя
  const key = crypto.scryptSync(pw, salt, 64, { N: 16384, r: 8, p: 1 });
  return `scrypt$${salt.toString('hex')}$${key.toString('hex')}`;
}

function checkPassword(pw, stored) {
  const [, saltHex, keyHex] = stored.split('$');
  const salt = Buffer.from(saltHex, 'hex');
  const expected = Buffer.from(keyHex, 'hex');
  const actual = crypto.scryptSync(pw, salt, expected.length, { N: 16384, r: 8, p: 1 });
  return crypto.timingSafeEqual(actual, expected); // за постоянное время
}

function readToken(token, key) {
  return jwt.verify(token, key, {
    algorithms: ['RS256'],          // никогда не давать токену выбирать → убивает alg:none + путаницу HS/RS
    issuer: 'https://auth.example.com',
    audience: 'api://orders',
    maxAge: '15m',
  });
}

Почему верно: scrypt медленный и memory-hard, настроен на ~100–250 мс, так что миллиарды-в-секунду GPU схлопываются до пары попыток/ядро; случайная соль на пользователя бьёт радужные таблицы; timingSafeEqual сканирует всю длину, так что побайтовое восстановление по времени невозможно. Закрепление алгоритмов на единственном значении из allow-листа останавливает и alg:none (нет проверки подписи), и путаницу RS256/HS256 (подпись публичным ключом как HMAC-секретом); issuer/audience/maxAge гарантируют, что токен выпущен для тебя и не бессмертен.
